refentry.refsect1:
&reftitle.description;
boolis_subclass_of mixedobject_or_class stringclass boolallow_string&true;
Verifica se l'object_or_class dato ha la classe class come uno dei suoi genitori o la implementa.

  &reftitle.examples;



    Esempio di is_subclass_of


<?php
// definisce una classe
class WidgetFactory
{
  var $oink = 'moo';
}

// definisce una classe figlia
class WidgetFactory_Child extends WidgetFactory
{
  var $oink = 'oink';
}

// crea un nuovo oggetto
$WF = new WidgetFactory();
$WFC = new WidgetFactory_Child();

if (is_subclass_of($WFC, 'WidgetFactory')) {
  echo "sì, \$WFC è una sottoclasse di WidgetFactory\n";
} else {
  echo "no, \$WFC non è una sottoclasse di WidgetFactory\n";
}


if (is_subclass_of($WF, 'WidgetFactory')) {
  echo "sì, \$WF è una sottoclasse di WidgetFactory\n";
} else {
  echo "no, \$WF non è una sottoclasse di WidgetFactory\n";
}


if (is_subclass_of('WidgetFactory_Child', 'WidgetFactory')) {
  echo "sì, WidgetFactory_Child è una sottoclasse di WidgetFactory\n";
} else {
  echo "no, WidgetFactory_Child non è una sottoclasse di WidgetFactory\n";
}
?>


    &example.outputs;


sì, $WFC è una sottoclasse di WidgetFactory
no, $WF non è una sottoclasse di WidgetFactory
sì, WidgetFactory_Child è una sottoclasse di WidgetFactory







    Esempio di is_subclass_of usando un'interfaccia


<?php
// Definisce l'interfaccia
interface MyInterface
{
  public function MyFunction();
}

// Definisce la classe che implementa l'interfaccia
class MyClass implements MyInterface
{
  public function MyFunction()
  {
    return "MyClass implementa MyInterface!";
  }
}

// Istanzia l'oggetto
$my_object = new MyClass;

// Funziona a partire da 5.3.7

// Test usando l'istanza dell'oggetto della classe
if (is_subclass_of($my_object, 'MyInterface')) {
  echo "Sì, \$my_object è una sottoclasse di MyInterface\n";
} else {
  echo "No, \$my_object non è una sottoclasse di MyInterface\n";
}

// Test usando una stringa con il nome della classe
if (is_subclass_of('MyClass', 'MyInterface')) {
  echo "Sì, MyClass è una sottoclasse di MyInterface\n";
} else {
  echo "No, MyClass non è una sottoclasse di MyInterface\n";
}
?>


    &example.outputs;


Sì, $my_object è una sottoclasse di MyInterface
Sì, MyClass è una sottoclasse di MyInterface
